  "tip": "非創傷性肩部攝影。仰臥、患側手臂外展 90°，X 光管置於腋下，CR 由下向上（inferosuperior，故平行身體長軸）射入，並向內側（medial）偏轉 25° 以顯示肱骨頭與肩盂關節間隙。可顯示：肱骨頭前後徑、關節盂、肱骨頭與盂之關節間隙、鎖骨下緣、肱骨頭骨折與脫臼。（放診114-2 第10題）。(正常應使用可攜式影像板，但本程式尚未加入此功能，因此用直立架影像板代替，靜待之後更新)",
